assert [c['id'] for c in C] == [f'{PRE}-{i:02d}' for i in range(1, len(C) + 1)] and len(CI) == 42
json.dump(C, open(out, 'w', encoding='utf-8'), ensure_ascii=False, indent=1); open(out, 'a', encoding='utf-8').write('\n')
print(f'{UID}: {len(C)} claims ({PRE}) -> {out}; cite index {len(CI)}; checks {[c["check"]["contains"] for c in C]}')
